getCalendarEventsOverlappingMonths(courseId: number, monthKeys: Array<string>, timeZone: string, language: 'ENGLISH' | 'GERMAN'): Observable<{ [key: string]: Array<CalendarEvent>; }> {
    const queryParams = new URLSearchParams();
    if (monthKeys !== undefined && monthKeys !== null) {
        monthKeys.forEach(item => queryParams.append('monthKeys', String(item)));
    }
    if (timeZone !== undefined && timeZone !== null) {
        queryParams.set('timeZone', String(timeZone));
    }
    if (language !== undefined && language !== null) {
        queryParams.set('language', String(language));
    }
    const queryString = queryParams.toString();
    const url = `${this.basePath}/api/calendar/courses/${courseId}/calendar-events${queryString ? `?${queryString}` : ''}`;
    return this.http.get<{ [key: string]: Array<CalendarEvent>; }>(url);
}

