// The Angular client is generated by our custom de.tum.cit.aet:openapi-generator-angular22:1.0.0
// generator (generatorName "angular22"): standalone, inject()-based services (no constructor
// injection — required for the AnalogJS fastCompile test runner under Angular 22) and
// signal/readonly-aware models. The generator is added to the buildscript classpath (only for the
// openApiGenerate task) in the root build.gradle, which also documents how to obtain it (Maven
// Central — no auth — or build-from-source via publishToMavenLocal). The generated client is
// committed, so CI never runs openApiGenerate.
openApiGenerate {
    generatorName = "angular22"
    inputSpec.set(file("${rootDir}/openapi/openapi.yaml").toURI().toString())
    outputDir = "${rootDir}/src/main/webapp/app/openapi"
    apiPackage = "api"
    modelPackage = "model"
    // sets are not properly converted to JSON objects, so we need to use Array instead https://github.com/OpenAPITools/openapi-generator/issues/14055
    // empty responses should be void, not object
    typeMappings = [
            set: 'Array',
    ]
    languageSpecificPrimitives =['void']
    // useHttpResource=false: classical HttpClient.get() Observable methods (not the signal-based
    // httpResource API). useInjectFunction=true: inject() instead of constructor injection.
    // readonlyModels=false: keep DTO properties mutable (Artemis builds/edits DTOs in place).
    configOptions = [
        useHttpResource  : "false",
        useInjectFunction: "true",
        separateResources: "false",
        readonlyModels   : "false"
    ]
}

tasks.register('pruneOpenApiSpec') {
    description = 'Prune invalid $ref nodes and drop operations (and empty paths) with missing schemas'

    doLast {
        def projectRoot = project.rootDir
        def inputFile = file("${projectRoot}/openapi/openapi.yaml")
        def outputFile = file("${projectRoot}/openapi/openapi.yaml")
        def yamlParser = new Yaml()

        Map<String, Object> specificationMap =
            yamlParser.load(inputFile.text) as Map<String, Object>

        Map<String, Map<String, Object>> componentsMap =
            (specificationMap.components ?: [:]) as Map<String, Map<String, Object>>

        Map<String, Object> prunedSpecificationMap =
            pruneInvalidReferences(specificationMap, componentsMap)

        removeOperationsWithNullSchemas(prunedSpecificationMap)
        flattenDiscriminatorAllOfBackReferences(prunedSpecificationMap)

        outputFile.text = yamlParser.dump(prunedSpecificationMap)
        // SnakeYAML's dump() converts double-quoted strings to single quotes.
        // The version line must use double quotes for update_version.sh --check.
        outputFile.text = outputFile.text.replaceFirst(
            /(?m)^(  version: )'([^']+)'$/, '$1"$2"'
        )

tasks.named('openApiGenerate') {
